<script setup>
import { ref,computed,watch,onMounted,onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { api,state,speak,refresh,notify } from '../api'
import Icon from '../components/Icon.vue'
const route=useRoute(),mode=ref(route.query.mode || 'mixed'),topic=ref(route.query.topic || ''),queue=ref([]),index=ref(0),revealed=ref(false),loading=ref(true),busy=ref(false),error=ref(''),started=ref(false),eventId=ref(''),retryRating=ref('')
const current=computed(()=>queue.value[index.value]),finished=computed(()=>started.value && queue.value.length>0 && index.value>=queue.value.length)
const ratings=[['again','Chưa nhớ','Ôn lại sau 10 phút'],['hard','Hơi khó','Ôn lại sớm'],['good','Đã nhớ','Giãn lịch ôn'],['easy','Rất dễ','Ôn lại lâu hơn']]
async function start(){loading.value=true;error.value='';try{const params=new URLSearchParams({mode:mode.value,limit:20});if(topic.value)params.set('topic_id',topic.value);queue.value=await api('/review?'+params);index.value=0;revealed.value=false;retryRating.value='';eventId.value=crypto.randomUUID();started.value=true}catch(e){error.value=e.message}finally{loading.value=false}}
async function rate(rating){if(busy.value || !current.value || (retryRating.value && retryRating.value!==rating))return;busy.value=true;error.value='';try{await api('/review',{method:'POST',body:JSON.stringify({word_id:current.value.id,rating,event_id:eventId.value})});index.value++;revealed.value=false;retryRating.value='';eventId.value=crypto.randomUUID();refresh().catch(e=>notify(e.message))}catch(e){retryRating.value=rating;error.value=e.message}finally{busy.value=false}}
function key(event){if(['INPUT','SELECT','TEXTAREA','BUTTON','A'].includes(event.target.tagName)||busy.value||!current.value)return;if(event.code==='Space'){event.preventDefault();revealed.value=!revealed.value}else if(revealed.value && /^[1-4]$/.test(event.key))rate(ratings[Number(event.key)-1][0])}
watch([mode,topic],start)
watch(()=>route.query,query=>{mode.value=query.mode || 'mixed';topic.value=query.topic || ''})
onMounted(()=>{start();window.addEventListener('keydown',key)})
onBeforeUnmount(()=>window.removeEventListener('keydown',key))
</script>
<template><div class="page study-page"><div class="page-heading"><div><div class="eyebrow">NHỚ LÂU HƠN, TỪNG CHÚT MỘT</div><h1>Học & ôn tập</h1><p>Nhìn từ, thử nhớ nghĩa, rồi tự đánh giá. Không cần vội.</p></div><span class="count-pill"><Icon name="Layers" :size="16"/>{{state.stats.due}} từ đến lịch ôn</span></div>
<div class="study-controls"><label>Chế độ<select v-model="mode" :disabled="busy || loading"><option value="mixed">Ôn đến hạn + học từ mới</option><option value="due">Chỉ ôn từ đến hạn</option><option value="new">Chỉ học từ mới</option><option value="saved">Học từ đã lưu</option></select></label><label>Chủ đề<select v-model="topic" :disabled="busy || loading"><option value="">Tất cả chủ đề</option><option v-for="t in state.topics" :key="t.id" :value="String(t.id)">{{t.name}}</option></select></label><span>Mỗi lượt tối đa 20 từ</span></div>
<div v-if="loading" class="loading-panel">Đang chuẩn bị thẻ học…</div><div v-else-if="error && !current" class="error-panel" role="alert">{{error}}<button class="btn outline" @click="start">Thử lại</button></div>
<div v-else-if="finished" class="session-complete"><div class="complete-icon"><Icon name="PartyPopper" :size="40"/></div><div class="eyebrow">MỘT BƯỚC TIẾN MỚI</div><h2>Bạn đã luyện {{queue.length}} từ!</h2><p>Lịch ôn tiếp theo đã được lưu. Những từ chưa nhớ sẽ trở lại sớm hơn.</p><div class="heading-actions"><button class="btn primary" @click="start">Học tiếp<Icon name="ArrowRight" :size="18"/></button><RouterLink to="/" class="btn outline">Xem tiến độ</RouterLink></div></div>
<div v-else-if="!current" class="empty-state"><Icon name="CircleCheck" :size="45"/><h2>{{mode==='saved' ? 'Bạn chưa lưu từ nào' : 'Không có từ cần học trong chế độ này'}}</h2><p>{{mode==='saved' ? 'Vào kho từ vựng và nhấn biểu tượng lưu để tạo bộ từ riêng.' : 'Bạn có thể chọn chủ đề khác hoặc học thêm từ mới.'}}</p><RouterLink to="/words" class="btn primary">Khám phá kho từ</RouterLink></div>
<div v-else class="study-workspace"><div class="study-progress"><span>THẺ {{index+1}} / {{queue.length}}</span><span>{{Math.round(index/queue.length*100)}}% hoàn thành</span><div class="progress-track"><span :style="{width:index/queue.length*100+'%'}"></span></div></div><section class="flashcard" :class="{revealed}"><div class="flashcard-top"><span class="word-topic" :style="{background:current.topic_color}">{{current.topic_name}}</span><span class="level">{{current.level}}</span></div><div class="flashcard-content"><span class="eyebrow">{{revealed ? 'NGHĨA & NGỮ CẢNH' : 'BẠN CÓ NHỚ TỪ NÀY KHÔNG?'}}</span><h2>{{current.term}}</h2><button class="audio-button" :aria-label="'Nghe '+current.term" @click="speak(current.term)"><Icon name="Volume2" :size="23"/>Nghe phát âm</button><template v-if="revealed"><h3>{{current.meaning}}</h3><p class="flash-example">“{{current.example}}”</p><button class="text-link" @click="speak(current.example)"><Icon name="Volume2" :size="16"/>Nghe câu ví dụ</button></template><p v-else class="flash-hint">Thử nói nghĩa hoặc đặt một câu với từ này.</p></div><button v-if="!revealed" class="btn primary reveal-button" @click="revealed=true">Hiện nghĩa<Icon name="RotateCw" :size="17"/></button><span v-else class="flash-footer">Bạn nhớ từ này đến mức nào?</span></section><div v-if="revealed" class="rating-grid"><button v-for="([rating,label,hint],i) in ratings" :key="rating" :class="['rating-button',rating]" :disabled="busy || (!!retryRating && retryRating!==rating)" @click="rate(rating)"><strong>{{retryRating===rating ? 'Thử lưu lại' : label}}<span>{{i+1}}</span></strong><small>{{hint}}</small></button></div><p v-if="error" class="form-error centered" role="alert">{{error}} · Nhấn “Thử lưu lại” để lưu lượt này.</p><p class="keyboard-tip">Phím <kbd>Space</kbd> để lật thẻ · <kbd>1</kbd>–<kbd>4</kbd> để đánh giá</p></div>
</div></template>
